extractor:
function extract(raw, memory, info) {
  info = info || {};
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.road) || typeof raw.playerX !== 'number') {
    memory.x = null; memory.t = null; memory.cars = {}; memory.target = null;
    return { ready: false };
  }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function r2(v) { return Math.round(v * 100) / 100; }
  var lag = clamp((+info.lagMs || 0) / 1000, 0, 0.5);
  var TICK = 0.096, H = 2.0, DT = 0.03, MARGIN = 0.08;
  var seg = +raw.segmentLength || 200;
  var MAXV = seg * 60;
  var cf = typeof raw.centrifugal === 'number' ? raw.centrifugal : 0.3;
  var pw = +raw.playerW || 0.3;
  var s = clamp(+raw.speed || 0, 0, 1);
  var x0 = raw.playerX;
  var road = raw.road;
  function cv(i) { var r = road[Math.min(i, road.length - 1)]; return r ? (+r.curve || 0) : 0; }
  var now = typeof info.nowMs === 'number' ? info.nowMs : (typeof memory.t === 'number' ? memory.t + 96 : 0);
  var dt = typeof memory.t === 'number' ? (now - memory.t) / 1000 : 0;
  if (!(dt > 0.005 && dt < 0.5)) dt = 0;
  var c0 = cv(0), cL = cv(Math.round(60 * s * lag));
  var vx = -2 * cf * s * s * c0;
  if (dt && typeof memory.x === 'number') {
    var lim = 2 * s + Math.abs(vx) + 0.05;
    vx = clamp((x0 - memory.x) / dt, -lim, lim);
  }
  var xL = x0 + vx * lag;
  memory.x = x0; memory.t = now;
  var i, k;
  var prev = memory.cars || {}, seen = {}, cars = [];
  var list = Array.isArray(raw.cars) ? raw.cars : [];
  for (i = 0; i < list.length; i++) {
    var c = list[i];
    if (!c || typeof c !== 'object') continue;
    var o = +c.offset || 0, w = +c.w || 0.3, cs = +c.speed || 0, dz = +c.dz || 0;
    var key = w.toFixed(3) + '|' + cs.toFixed(3);
    var cvx = 0;
    if (dt && typeof prev[key] === 'number' && Math.abs(o - prev[key]) < 0.5) cvx = clamp((o - prev[key]) / dt, -1.5, 1.5);
    seen[key] = o;
    cars.push({ o: o, cs: cs, dz: dz, vx: cvx, half: 0.4 * (pw + w) + MARGIN });
  }
  memory.cars = seen;
  var STEPS = Math.round(H / DT), spA = [], pzA = [], sp0 = s, pz0 = s * MAXV * lag;
  for (k = 0; k < STEPS; k++) { sp0 = Math.min(1, sp0 + 0.2 * DT); pz0 += sp0 * MAXV * DT; spA.push(sp0); pzA.push(pz0); }
  function sim(target, steer) {
    var x = xL;
    for (var k = 0; k < STEPS; k++) {
      var sp = spA[k], ct = lag + (k + 1) * DT;
      if (steer) { var d = target - x, mv = 1.7 * sp * DT; x += Math.abs(d) <= mv ? d : (d > 0 ? mv : -mv); }
      for (var j = 0; j < cars.length; j++) {
        var c = cars[j];
        if (sp <= c.cs) continue;
        var rel = c.dz + c.cs * MAXV * ct - pzA[k];
        if (rel <= -seg || rel >= seg) continue;
        if (Math.abs(x - (c.o + c.vx * Math.min(ct, 0.3))) < c.half) return { t: (k + 1) * DT, c: c };
      }
    }
    return null;
  }
  var cMax = 0;
  for (i = 0; i < road.length; i++) { var cc = cv(i); if (Math.abs(cc) > Math.abs(cMax)) cMax = cc; }
  var hold = cf * Math.abs(cMax) * s;
  var bias = (cMax > 0 ? 1 : (cMax < 0 ? -1 : 0)) * 0.2 * clamp((hold - 0.6) / 0.4, 0, 1);
  var cands = [clamp(xL, -0.8, 0.8)];
  for (i = -6; i <= 6; i++) cands.push(i * 0.125);
  var pt = memory.target, best = null, bestSc = -1e9, leftT = 0, rightT = 0;
  for (i = 0; i < cands.length; i++) {
    var xc = cands[i], h = sim(xc, true), th = h ? h.t : H;
    var sc = th - 0.08 * Math.abs(xc - xL) + bias * xc;
    if (typeof pt === 'number' && Math.abs(xc - pt) < 0.07) sc += 0.04;
    if (sc > bestSc + 1e-9) { bestSc = sc; best = { x: xc, t: th, c: h ? h.c : null }; }
    if (xc < xL - 0.1 && th > leftT) leftT = th;
    if (xc > xL + 0.1 && th > rightT) rightT = th;
  }
  memory.target = best.x;
  var lh = sim(xL, false);
  var lineHitMs = lh ? Math.round(lh.t * 1000) : 2000;
  var slowMarginMs = 2000;
  if (best.c) slowMarginMs = Math.round((best.t - Math.max(0, s - best.c.cs) / 2) * 1000);
  var xNo = xL - 2 * cf * s * s * cL * TICK;
  var openDxSteps = clamp((best.x - xNo) / (2 * Math.max(s, 0.05) * TICK), -9.9, 9.9);
  var edgeMs = 3000;
  if (Math.abs(xL) > 1) edgeMs = 0;
  else if (s > 0.02) {
    var segT = 1 / (60 * s), xs = xL, tE = -1, net = 0, dir = 0;
    for (i = 0; i < road.length; i++) {
      var c1 = cv(i);
      net = 2 * cf * s * Math.abs(c1) / 60 - 1 / 30;
      dir = c1 > 0 ? -1 : (c1 < 0 ? 1 : 0);
      if (dir && net > 0) xs += dir * net;
      if (Math.abs(xs) > 1) { tE = i * segT; break; }
    }
    if (tE < 0 && dir && net > 0) tE = road.length * segT + (dir > 0 ? 1 - xs : xs + 1) * segT / net;
    if (tE >= 0) edgeMs = Math.min(3000, Math.round(tE * 1000));
  }
  var sideObjMs = 3000, side = Array.isArray(raw.side) ? raw.side : [];
  if (Math.abs(xL) > 0.9 && s > 0.02) {
    for (i = 0; i < side.length; i++) {
      var so = side[i];
      if (!so || typeof so !== 'object') continue;
      var off = +so.offset || 0, sw = +so.w || 0.5;
      var ctr = off + (off > 0 ? 1 : -1) * sw / 2;
      if (Math.abs(xL - ctr) > (pw + sw) / 2) continue;
      var ts = Math.max(0, (+so.dz || 0) - seg - s * MAXV * lag) / (s * MAXV);
      sideObjMs = Math.min(sideObjMs, Math.round(ts * 1000));
    }
  }
  return {
    ready: true,
    speed: r2(s),
    x: r2(xL),
    offRoad: Math.abs(xL) > 1,
    curve: Math.round(cL * 10) / 10,
    edgeMs: edgeMs,
    openX: r2(best.x),
    openDxSteps: Math.round(openDxSteps * 10) / 10,
    openClearMs: Math.round(best.t * 1000),
    slowMarginMs: slowMarginMs,
    lineHitMs: lineHitMs,
    leftOpenMs: Math.round(leftT * 1000),
    rightOpenMs: Math.round(rightT * 1000),
    sideObjMs: sideObjMs
  };
}

teacher:
function teach(state) {
  if (!state || !state.ready) return 'gas';
  var side = state.openDxSteps >= 0.5 ? 'Right' : (state.openDxSteps <= -0.5 ? 'Left' : '');
  var slow = !state.offRoad && state.speed > 0.05 && (state.slowMarginMs < 150 || (state.edgeMs < 700 && state.speed > 0.3));
  return (slow ? 'brake' : 'gas') + side;
}
